  INSERT INTO public.regattas (
    name, slug, event_id, date, end_date, total_fleet_size, division, race_count,
    geography, boat_class, counts_for_ranking, venue, organizer, schedule_notes, status, reviewed_at
  ) VALUES (
    'Raffles Marina ILCA Championship 2024 (ILCA 6)', 'raffles-marina-ilca6-mar-2024', v_event, DATE '2024-03-23', DATE '2024-03-24',
    15, 'Open', 7, 'SGP', 'ILCA 6', true,
    'Raffles Marina, Singapore', 'Raffles Marina', 'Official final results, visually reviewed. Seven races completed.', 'published', now()
  ) ON CONFLICT (slug) DO UPDATE SET
    name = EXCLUDED.name, event_id = EXCLUDED.event_id, date = EXCLUDED.date, end_date = EXCLUDED.end_date,
    total_fleet_size = EXCLUDED.total_fleet_size, division = EXCLUDED.division, race_count = EXCLUDED.race_count,
